// The shapes everything in Ward passes around: a chat the child shared in, what each message
// was judged to be, and the patterns that only show up across many messages.

export type Category =
  | "insult" // name-calling, put-downs
  | "appearance" // body, face, skin, clothes
  | "identity" // religion, caste, ethnicity, gender, sexuality, disability
  | "exclusion" // "don't add her", "nobody wants you here"
  | "threat" // physical harm, "wait till school"
  | "selfharm" // telling someone to hurt or kill themselves
  | "sexual" // sexual comments, pressure, image requests
  | "exposure" // leaking photos, screenshots, address, phone number
  | "mockery"; // laughing at someone, humiliation

export const CATEGORIES: readonly Category[] = [
  "insult",
  "appearance",
  "identity",
  "exclusion",
  "threat",
  "selfharm",
  "sexual",
  "exposure",
  "mockery",
];

/** 0 nothing, 1 rude or unkind, 2 bullying, 3 dangerous (threats, self-harm urging, sexual, exposure). */
export type Severity = 0 | 1 | 2 | 3;

export interface Message {
  id: number;
  /** null when the source had no timestamps (pasted text). */
  at: Date | null;
  sender: string;
  text: string;
  /** "<Media omitted>", a deleted message, or a photo the source dropped. */
  media: boolean;
}

/** Group events from a WhatsApp export: joins, adds, removals, leaving. */
export interface ChatEvent {
  at: Date | null;
  kind: "joined" | "added" | "removed" | "left";
  /** Who joined, was added, was removed, or left. */
  who: string;
  /** Who did the adding or removing, when the export says. */
  by?: string;
  /** Index of the next message after this event, so events sort into the timeline. */
  before: number;
}

export interface Chat {
  source: "whatsapp" | "paste";
  messages: Message[];
  events: ChatEvent[];
  participants: string[];
}

export interface PackHit {
  term: string;
  lang: string;
  category: Category;
  severity: Severity;
  /** What it means, in English, for the explanation. */
  gloss: string;
}

/** What a model said about one message. */
export interface ModelJudgement {
  hostile: boolean;
  severity: Severity;
  categories: Category[];
  /** Who it is aimed at, if the model could tell. */
  target?: string;
  /** One short reason, for the timeline. */
  why?: string;
  /** Which model said it, for the scorecard and the "how Ward knows" panel. */
  model: string;
}

export interface Finding {
  message: Message;
  severity: Severity;
  categories: Category[];
  hits: PackHit[];
  model?: ModelJudgement;
  /** Aimed at the child (by name, reply, or a model's call), as far as Ward can tell. */
  atSelf: boolean;
  why: string;
}

export type PatternKind =
  | "campaign" // one person, again and again, across days
  | "pileon" // many people at once
  | "ghosts" // accounts that joined and only attacked
  | "exclusion" // shutting someone out
  | "danger" // threats, self-harm urging, sexual pressure, exposure
  | "nightwatch" // attacks in the small hours
  | "escalating"; // getting worse over time

export interface Pattern {
  kind: PatternKind;
  /** Who is doing it. */
  senders: string[];
  messageIds: number[];
  /** One sentence for the child. Age-neutral; the UI adapts the tone. */
  summary: string;
}

export type Level = "calm" | "watch" | "bullying" | "urgent";

export interface Analysis {
  level: Level;
  self: string | null;
  findings: Finding[];
  patterns: Pattern[];
  /** Per sender: hostile messages, worst severity. Sorted worst first. */
  senders: { name: string; hostile: number; worst: Severity; total: number }[];
  /** Which layers ran, so the UI can say how sure Ward is. */
  layers: { packs: string[]; models: string[] };
}

// Text as kids actually type it: "kuttaaaa", "b!tch", "l00ser", zero-width tricks, mixed scripts.
// normalize() folds those into one spelling so a slang pack entry catches all of them.

const LEET: Record<string, string> = {
  "0": "o",
  "1": "i",
  "3": "e",
  "4": "a",
  "5": "s",
  "7": "t",
  "@": "a",
  $: "s",
  "!": "i",
  "|": "i",
};

const ZERO_WIDTH = /[​-‍⁠﻿­]/g;

export function normalize(text: string): string {
  let s = text.normalize("NFKC").replace(ZERO_WIDTH, "").toLowerCase();
  // Latin diacritics only; Urdu, Hindi and Bangla script pass through untouched.
  s = s.normalize("NFD").replace(/[̀-ͯ]/g, "").normalize("NFC");
  // Leetspeak inside words ("l00ser", "b!tch"), but leave standalone numbers alone.
  s = s.replace(/(?<=\p{L})[013457@$!|]+|[013457@$!|]+(?=\p{L})/gu, (m) =>
    [...m].map((c) => LEET[c] ?? c).join(""),
  );
  // "kuttaaaaa" -> "kuttaa", "stoooopid" -> "stoopid": keeps real doubles.
  s = s.replace(/(\p{L})\1{2,}/gu, "$1$1");
  // "s.t.u.p.i.d" and "s t u p i d" -> "stupid" (single letters split by dots or spaces).
  s = s.replace(/\b(?:\p{L}[.\s*_-]){3,}\p{L}\b/gu, (m) => m.replace(/[.\s*_-]/g, ""));
  return s.replace(/\s+/g, " ").trim();
}

/** Words, keeping Urdu, Devanagari and Bangla letters and joining marks. */
export function words(normalized: string): string[] {
  return normalized.match(/[\p{L}\p{M}']+/gu) ?? [];
}

/**
 * A rough sound-skeleton for Roman Urdu and Hinglish, where one word has many spellings:
 * "bewakoof", "bewkuf", "bevakoof" all become "bvkf". Vowels go, doubled letters collapse,
 * and look-alike sounds merge. Only used for pack terms of 5+ letters, to keep false hits rare.
 */
export function skeleton(word: string): string {
  return word
    .replace(/w/g, "v")
    .replace(/ph/g, "f")
    .replace(/q/g, "k")
    .replace(/z/g, "j")
    .replace(/(?<=.)[aeiouy]/g, "")
    .replace(/h(?=$)/, "")
    .replace(/(.)\1+/g, "$1");
}

// Slang packs: plain JSON lists a teacher or a youth group can edit, one per language.
// They are the layer that works with no model at all, on the cheapest phone, instantly.

import en from "../packs/en.json" with { type: "json" };
import urLatn from "../packs/ur-Latn.json" with { type: "json" };
import hiLatn from "../packs/hi-Latn.json" with { type: "json" };
import bn from "../packs/bn.json" with { type: "json" };
import { normalize, skeleton, words } from "./normalize.ts";
import type { Category, PackHit, Severity } from "./types.ts";

export interface PackEntry {
  /** The word or phrase, written the most common way. */
  t: string;
  c: Category;
  s: Severity;
  /** English meaning. */
  g: string;
}

export interface Pack {
  lang: string;
  name: string;
  about?: string;
  entries: PackEntry[];
}

export const STARTER_PACKS: Pack[] = [en, urLatn, hiLatn, bn] as Pack[];

interface Compiled {
  entry: PackEntry;
  lang: string;
  tokens: string[];
}

const LATIN = /^[a-z']+$/;

/** "kutta" -> "kutt": so "kutte", "kutti", "kuttay" all match. */
function stem(w: string): string {
  return w.replace(/[aeiouy]+$/, "");
}

function tokenMatches(text: string, term: string): boolean {
  if (text === term) return true;
  if (!LATIN.test(term) || term.length < 4) return false;
  if (Math.abs(text.length - term.length) <= 2 && stem(text).length >= 3 && stem(text) === stem(term)) return true;
  if (term.length >= 6 && text.length >= 5) {
    const sk = skeleton(term);
    return sk.length >= 4 && skeleton(text) === sk;
  }
  return false;
}

function prep(text: string): string[] {
  return words(normalize(text).replace(/['’]/g, ""));
}

export class PackMatcher {
  private compiled: Compiled[];
  readonly langs: string[];

  constructor(packs: Pack[] = STARTER_PACKS) {
    this.langs = packs.map((p) => p.lang);
    this.compiled = packs.flatMap((p) =>
      p.entries.map((entry) => ({ entry, lang: p.lang, tokens: prep(entry.t) })).filter((c) => c.tokens.length > 0),
    );
  }

  match(text: string): PackHit[] {
    const toks = prep(text);
    const hits: PackHit[] = [];
    const seen = new Set<string>();
    for (const { entry, lang, tokens } of this.compiled) {
      if (seen.has(entry.t)) continue;
      for (let i = 0; i + tokens.length <= toks.length; i++) {
        if (tokens.every((t, j) => tokenMatches(toks[i + j]!, t))) {
          hits.push({ term: entry.t, lang, category: entry.c, severity: entry.s, gloss: entry.g });
          seen.add(entry.t);
          break;
        }
      }
    }
    // A longer phrase that matched swallows the shorter ones inside it ("fat pig" over "pig").
    return hits.filter((h) => !hits.some((o) => o !== h && o.term.length > h.term.length && o.term.includes(h.term)));
  }
}

// Getting a chat into Ward. Kids share a WhatsApp export (the .txt from "Export chat") or paste
// text. Both phone formats are handled:
//   Android: 12/10/2026, 21:14 - Ali: text
//   iPhone:  [12/10/2026, 21:14:05] Ali: text
// plus 12-hour times ("9:14 pm"), dotted dates, multi-line messages and group events.

import type { Chat, ChatEvent, Message } from "./types.ts";

const ANDROID = /^(\d{1,4}[./-]\d{1,2}[./-]\d{1,4}),? (\d{1,2}:\d{2}(?::\d{2})?)(?:\s?([ap]\.?m\.?))? - (.*)$/i;
const IOS = /^‎?\[(\d{1,4}[./-]\d{1,2}[./-]\d{1,4}),? (\d{1,2}:\d{2}(?::\d{2})?)(?:\s?([ap]\.?m\.?))?\] (.*)$/i;
const MEDIA = /^(?:‎)?(?:<media omitted>|<attached: .*>|image omitted|video omitted|sticker omitted|gif omitted|audio omitted|this message was deleted|you deleted this message)$/i;

interface Dated {
  date: string;
  time: string;
  ampm?: string;
  rest: string;
}

/** Day/month order varies by phone locale; decide once per chat from dates that can only be read one way. */
function dayFirst(dates: string[]): boolean {
  for (const d of dates) {
    const [a, b] = d.split(/[./-]/).map(Number);
    if (a! > 12) return true;
    if (b! > 12) return false;
  }
  return true;
}

function toDate(d: Dated, df: boolean): Date | null {
  const parts = d.date.split(/[./-]/).map(Number);
  let [a, b, c] = parts as [number, number, number];
  let year: number, month: number, day: number;
  if (a > 31) [year, month, day] = [a, b, c];
  else [day, month, year] = df ? [a, b, c] : [b, a, c];
  if (year < 100) year += 2000;
  const [h, m, s] = d.time.split(":").map(Number) as [number, number, number?];
  let hour = h;
  const ap = d.ampm?.toLowerCase().replace(/\./g, "");
  if (ap === "pm" && hour < 12) hour += 12;
  if (ap === "am" && hour === 12) hour = 0;
  const date = new Date(year, month - 1, day, hour, m, s ?? 0);
  return Number.isNaN(date.getTime()) ? null : date;
}

function event(rest: string): Omit<ChatEvent, "at" | "before"> | null {
  const r = rest.replace(/‎/g, "");
  let m = r.match(/^(.+?) joined using this group's invite link$/i);
  if (m) return { kind: "joined", who: m[1]! };
  m = r.match(/^(.+?) joined$/i);
  if (m) return { kind: "joined", who: m[1]! };
  m = r.match(/^(.+?) added (.+)$/i);
  if (m) return { kind: "added", who: m[2]!, by: m[1]! };
  m = r.match(/^(.+?) removed (.+)$/i);
  if (m) return { kind: "removed", who: m[2]!, by: m[1]! };
  m = r.match(/^(.+?) left$/i);
  if (m) return { kind: "left", who: m[1]! };
  return null;
}

export function parseWhatsApp(text: string): Chat | null {
  const lines = text.replace(/\r\n?/g, "\n").split("\n");
  const dated: (Dated | string)[] = lines.map((line) => {
    const m = line.match(IOS) ?? line.match(ANDROID);
    return m ? { date: m[1]!, time: m[2]!, ampm: m[3], rest: m[4]! } : line;
  });
  const heads = dated.filter((d): d is Dated => typeof d !== "string");
  if (heads.length < 2 || heads.length < lines.filter((l) => l.trim()).length * 0.3) return null;
  const df = dayFirst(heads.map((h) => h.date));

  const messages: Message[] = [];
  const events: ChatEvent[] = [];
  let last: Message | null = null;
  for (const d of dated) {
    if (typeof d === "string") {
      if (last && d.trim()) last.text += "\n" + d;
      continue;
    }
    const at = toDate(d, df);
    const colon = d.rest.indexOf(": ");
    if (colon === -1) {
      const ev = event(d.rest);
      if (ev) events.push({ ...ev, at, before: messages.length });
      last = null; // system lines ("Messages are end-to-end encrypted") have no continuation
      continue;
    }
    const sender = d.rest.slice(0, colon).replace(/‎/g, "").trim();
    const body = d.rest.slice(colon + 2);
    last = { id: messages.length, at, sender, text: body, media: MEDIA.test(body.trim()) };
    messages.push(last);
  }
  return { source: "whatsapp", messages, events, participants: participantsOf(messages, events) };
}

/** Pasted text: "Name: message" per line where it can, otherwise one message per line. */
export function parsePasted(text: string): Chat {
  const lines = text.replace(/\r\n?/g, "\n").split("\n").filter((l) => l.trim());
  const named = lines.filter((l) => /^[^:\n]{1,40}: \S/.test(l)).length;
  const messages: Message[] = [];
  for (const line of lines) {
    const m = named >= lines.length / 2 ? line.match(/^([^:\n]{1,40}): (.*)$/) : null;
    if (!m && named >= lines.length / 2 && messages.length) {
      messages[messages.length - 1]!.text += "\n" + line;
      continue;
    }
    const text = m ? m[2]! : line;
    messages.push({ id: messages.length, at: null, sender: m ? m[1]!.trim() : "Someone", text, media: MEDIA.test(text.trim()) });
  }
  return { source: "paste", messages, events: [], participants: participantsOf(messages, []) };
}

export function parseChat(text: string): Chat {
  return parseWhatsApp(text) ?? parsePasted(text);
}

function participantsOf(messages: Message[], events: ChatEvent[]): string[] {
  const count = new Map<string, number>();
  for (const m of messages) count.set(m.sender, (count.get(m.sender) ?? 0) + 1);
  for (const e of events) if (!count.has(e.who)) count.set(e.who, 0);
  return [...count.entries()].sort((a, b) => b[1] - a[1]).map(([n]) => n);
}

// From messages to what's happening. One mean message is rude; bullying is a pattern:
// the same person again and again, many people at once, accounts that show up only to attack.
// This file turns per-message judgements into those patterns and one overall level.

import { PackMatcher } from "./packs.ts";
import type { Analysis, Category, Chat, Finding, Level, Message, ModelJudgement, Pattern, Severity } from "./types.ts";

export interface Judge {
  /** Shown in "how Ward knows", e.g. "gemma4:e4b". */
  name: string;
  judge(chat: Chat, opts: { self: string | null; onProgress?: (done: number, total: number) => void }): Promise<Map<number, ModelJudgement>>;
}

export interface AnalyzeOptions {
  /** Which participant is the child using Ward. */
  self: string | null;
  packs?: PackMatcher;
  judges?: Judge[];
  onProgress?: (done: number, total: number) => void;
}

const SECOND_PERSON = /\b(you|u|ur|your|yours|tu|tum|tujhe|tujh|tera|teri|tere|tumhara|tumhari|aap|tui|tor|tomake|tomar|toke)\b/i;
const HOUR = 3_600_000;
const DAY = 24 * HOUR;

function firstName(name: string): string {
  return name.split(/\s+/)[0]!.toLowerCase();
}

function mentions(text: string, name: string): boolean {
  const n = firstName(name);
  if (n.length < 2) return false;
  return new RegExp(`(^|[^\\p{L}])@?${n.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}([^\\p{L}]|$)`, "iu").test(text);
}

function aimedAtSelf(chat: Chat, m: Message, self: string | null, model?: ModelJudgement): boolean {
  if (!self || m.sender === self) return false;
  if (model?.target && firstName(model.target) === firstName(self)) return true;
  if (mentions(m.text, self)) return true;
  // A one-to-one chat: everything the other person says is to the child.
  if (chat.participants.filter((p) => p !== self).length <= 1) return true;
  // "you" shortly after the child spoke.
  if (SECOND_PERSON.test(m.text)) {
    const recent = chat.messages.slice(Math.max(0, m.id - 6), m.id);
    if (recent.some((r) => r.sender === self)) return true;
  }
  // No better signal and the model was sure it was aimed somewhere: ask about the child's name.
  return model?.target == null && SECOND_PERSON.test(m.text) && chat.participants.length <= 3;
}

function combine(m: Message, matcher: PackMatcher, model: ModelJudgement | undefined) {
  const hits = matcher.match(m.text);
  const packSev = hits.reduce<Severity>((s, h) => (h.severity > s ? h.severity : s), 0);
  let severity: Severity = packSev;
  let why = hits.length ? hits.map((h) => `"${h.term}" (${h.gloss})`).join(", ") : "";
  if (model) {
    if (model.hostile) {
      severity = Math.max(model.severity, packSev >= 3 ? 3 : 1) as Severity;
      why = model.why ?? why;
    } else if (packSev >= 3) {
      // The model reads it as a joke, but the words are dangerous ones: keep it visible, don't panic.
      severity = 2;
      why = `${why}. It may be a joke, but these words are serious. How did it feel?`;
    } else {
      severity = 0;
    }
  }
  const categories = [...new Set<Category>([...hits.map((h) => h.category), ...(model?.hostile ? model.categories : [])])];
  return { hits, severity, categories, why };
}

function sameDay(a: Date, b: Date) {
  return a.toDateString() === b.toDateString();
}

export async function analyze(chat: Chat, opts: AnalyzeOptions): Promise<Analysis> {
  const matcher = opts.packs ?? new PackMatcher();
  const judgements = new Map<number, ModelJudgement>();
  const models: string[] = [];
  for (const j of opts.judges ?? []) {
    const got = await j.judge(chat, { self: opts.self, onProgress: opts.onProgress });
    models.push(j.name);
    // A later judge fills gaps; where both judged, the more worried one wins.
    for (const [id, v] of got) {
      const prev = judgements.get(id);
      if (!prev || (v.hostile && (!prev.hostile || v.severity > prev.severity))) judgements.set(id, v);
    }
  }

  const findings: Finding[] = chat.messages.map((m) => {
    const model = judgements.get(m.id);
    const c = combine(m, matcher, model);
    const atSelf = c.severity > 0 && aimedAtSelf(chat, m, opts.self, model);
    return { message: m, ...c, model, atSelf };
  });

  const hostile = findings.filter((f) => f.severity > 0 && f.message.sender !== opts.self);
  const toSelf = hostile.filter((f) => f.atSelf || !opts.self);
  const patterns = findPatterns(chat, hostile, toSelf, opts.self);

  const bySender = new Map<string, { name: string; hostile: number; worst: Severity; total: number }>();
  for (const m of chat.messages) {
    const s = bySender.get(m.sender) ?? { name: m.sender, hostile: 0, worst: 0 as Severity, total: 0 };
    s.total++;
    bySender.set(m.sender, s);
  }
  for (const f of hostile) {
    const s = bySender.get(f.message.sender)!;
    s.hostile++;
    if (f.severity > s.worst) s.worst = f.severity;
  }

  return {
    level: levelOf(patterns, toSelf),
    self: opts.self,
    findings,
    patterns,
    senders: [...bySender.values()].sort((a, b) => b.worst - a.worst || b.hostile - a.hostile),
    layers: { packs: matcher.langs, models },
  };
}

function levelOf(patterns: Pattern[], toSelf: Finding[]): Level {
  if (patterns.some((p) => p.kind === "danger")) return "urgent";
  if (patterns.some((p) => ["campaign", "pileon", "ghosts", "exclusion"].includes(p.kind))) return "bullying";
  if (toSelf.filter((f) => f.severity >= 2).length >= 3) return "bullying";
  if (toSelf.length > 0) return "watch";
  return "calm";
}

function ids(fs: Finding[]) {
  return fs.map((f) => f.message.id);
}

function uniq(xs: string[]) {
  return [...new Set(xs)];
}

export function findPatterns(chat: Chat, hostile: Finding[], toSelf: Finding[], self: string | null): Pattern[] {
  const out: Pattern[] = [];
  const timed = chat.messages.every((m) => m.at);

  const danger = hostile.filter((f) => f.severity >= 3);
  if (danger.length) {
    const kinds = uniq(danger.flatMap((f) => f.categories).filter((c) => ["threat", "selfharm", "sexual", "exposure"].includes(c)));
    const words: Record<string, string> = {
      threat: "threats to hurt you",
      selfharm: "telling you to hurt yourself",
      sexual: "sexual messages or pressure for photos",
      exposure: "threats to share photos or private things",
    };
    out.push({
      kind: "danger",
      senders: uniq(danger.map((f) => f.message.sender)),
      messageIds: ids(danger),
      summary: `This chat has ${kinds.map((k) => words[k]).filter(Boolean).join(", ") || "messages that could put you in danger"}. That is never okay, and it's not your fault.`,
    });
  }

  // The same person, again and again.
  const perSender = new Map<string, Finding[]>();
  for (const f of toSelf) perSender.set(f.message.sender, [...(perSender.get(f.message.sender) ?? []), f]);
  for (const [sender, fs] of perSender) {
    const days = timed ? uniq(fs.map((f) => f.message.at!.toDateString())).length : 0;
    if (fs.length >= 3 && (days >= 2 || (!timed && fs.length >= 4))) {
      out.push({
        kind: "campaign",
        senders: [sender],
        messageIds: ids(fs),
        summary: timed
          ? `${sender} has gone after you ${fs.length} times over ${days} days. When it keeps happening, it's bullying, not a joke.`
          : `${sender} has gone after you ${fs.length} times. When it keeps happening, it's bullying, not a joke.`,
      });
    }
  }

  // Many people at once: 3+ different senders inside an hour (or 15 messages, untimed).
  for (let i = 0; i < toSelf.length; i++) {
    const start = toSelf[i]!;
    const window = toSelf.filter((f, j) =>
      j >= i &&
      (timed ? f.message.at!.getTime() - start.message.at!.getTime() <= HOUR : f.message.id - start.message.id <= 15),
    );
    const senders = uniq(window.map((f) => f.message.sender));
    if (senders.length >= 3) {
      out.push({
        kind: "pileon",
        senders,
        messageIds: ids(window),
        summary: `${senders.length} people joined in on you at once. A pile-on can feel like everyone is against you. They aren't everyone.`,
      });
      break;
    }
  }

  // Accounts that turned up and only attacked.
  const arrived = new Set(chat.events.filter((e) => e.kind === "joined" || e.kind === "added").map((e) => e.who));
  const ghosts: string[] = [];
  for (const name of chat.participants) {
    if (name === self) continue;
    const mine = chat.messages.filter((m) => m.sender === name && !m.media);
    const bad = hostile.filter((f) => f.message.sender === name);
    if (!mine.length || !bad.length) continue;
    const ratio = bad.length / mine.length;
    if ((arrived.has(name) && ratio >= 0.6 && mine.length <= 8) || (bad.length >= 2 && ratio === 1 && mine.length <= 5 && chat.participants.length > 3)) {
      ghosts.push(name);
    }
  }
  if (ghosts.length) {
    out.push({
