  --glow: #ece5ae;
  --glow-ink: #1b1a08;
  --glow-soft: rgb(236 229 174 / 0.13);
  --halo: rgb(236 229 174 / 0.3);
}

[data-look="firefly"] {
  --bg: #0c140f;
  --surface: #131f17;
  --raised: #1b2c21;
  --line: rgb(220 245 210 / 0.09);
  --ink: #eff4e8;
  --dim: #a7b8a3;
  --glow: #c9ef5d;
  --glow-ink: #142000;
  --glow-soft: rgb(201 239 93 / 0.13);
  --halo: rgb(201 239 93 / 0.3);
}

[data-look="ember"] {
  --bg: #160e13;
  --surface: #21151c;
  --raised: #2d1d27;
  --line: rgb(255 225 225 / 0.09);
  --ink: #f7ece9;
  --dim: #c1a7ab;
  --glow: #ff8d6e;
  --glow-ink: #2a0a02;
  --glow-soft: rgb(255 141 110 / 0.14);
  --halo: rgb(255 141 110 / 0.34);
}

[data-look="aurora"] {
  --bg: #0a0f1e;
  --surface: #11192e;
  --raised: #192440;
  --line: rgb(210 230 255 / 0.09);
  --ink: #ebf2ff;
  --dim: #a2b2ce;
  --glow: #63eecb;
  --glow-ink: #02201a;
  --glow-soft: rgb(99 238 203 / 0.12);
  --halo: rgb(99 238 203 / 0.3);
}

/* The one light look, for daytime and for kids who find dark screens hard to read. */
[data-look="daylight"] {
  --bg: #eceef6;
  --surface: #f8f8fc;
  --raised: #e2e5f1;
  --line: rgb(23 24 58 / 0.1);
  --ink: #17183a;
  --dim: #50536f;
  --glow: #f0a12a;
  --glow-ink: #1f1200;
  --glow-soft: rgb(240 161 42 / 0.16);
  --halo: rgb(240 161 42 / 0.28);
}

:root {
  --alarm: #ff6f6f;
  --alarm-soft: rgb(255 111 111 / 0.13);
  --safe: #7fe0a8;
  --r-card: 22px;
  --r-btn: 16px;
  font-size: 17px;
}
[data-look="daylight"] {
  --alarm: #c42b2b;
  --alarm-soft: rgb(196 43 43 / 0.1);
  --safe: #1f7a49;
}

[data-age="8"] {
  --r-card: 28px;
  --r-btn: 22px;
  font-size: 18px;
}
[data-age="14"] {
  --r-card: 16px;
  --r-btn: 12px;
  font-size: 16px;
}

html,
body,
#root {
  min-height: 100dvh;
}

body {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}

/* The room's light: one soft pool of the look's glow, fixed behind everything. */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(60rem 40rem at 85% -10%, var(--glow-soft), transparent 60%),
    radial-gradient(40rem 30rem at -10% 110%, rgb(120 110 255 / 0.06), transparent 60%);
  z-index: 0;
}
[data-look="daylight"] body::before,
body[data-look="daylight"]::before {
  opacity: 0.6;
}

#root {
  position: relative;
  z-index: 1;
}

:focus-visible {
  outline: 3px solid var(--glow);
  outline-offset: 3px;
}

.font-display {
  font-variation-settings: "opsz" 48;
}

/* Ward's float, blink and the rim trail used by the drop zone. */
@keyframes ward-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-6px);
  }
}
@keyframes ward-blink {
  0%,
  92%,
  100% {
    transform: scaleY(1);
  }
  95% {
    transform: scaleY(0.1);
  }
}
@keyframes rim-trail {
  to {
    offset-distance: 100%;
  }
}
@keyframes rim-drift {
  0%,
  100% {
    transform: translateX(-30%);
  }
  50% {
    transform: translateX(30%);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

// Ward, the ghost on your side. The bully is the ghost haunting the chat; Ward is the one who
// leaves a light on. A simple geometric figure so it can change expression in lessons and in
// scary moments without a sprite sheet.

import { motion, useReducedMotion } from "motion/react";

export type Mood = "happy" | "cheer" | "calm" | "worried" | "think" | "sleep";

const BODY =
  "M20 70 A40 40 0 0 1 100 70 L100 118 q-6.67 10 -13.33 0 t-13.33 0 t-13.33 0 t-13.34 0 t-13.33 0 t-13.33 0 Z";

function Eyes({ mood }: { mood: Mood }) {
  const ink = "var(--bg)";
  if (mood === "cheer")
    return (
      <g fill="none" stroke={ink} strokeWidth="4" strokeLinecap="round">
        <path d="M41 74 q6 -9 12 0" />
        <path d="M67 74 q6 -9 12 0" />
      </g>
    );
  if (mood === "sleep" || mood === "calm")
    return (
      <g fill="none" stroke={ink} strokeWidth="4" strokeLinecap="round">
        <path d={mood === "sleep" ? "M41 72 q6 6 12 0" : "M42 72 q5 4 10 0"} />
        <path d={mood === "sleep" ? "M67 72 q6 6 12 0" : "M68 72 q5 4 10 0"} />
      </g>
    );
  const dx = mood === "think" ? 3 : 0;
  const dy = mood === "think" ? -3 : 0;
  return (
    <g fill={ink} style={{ transformOrigin: "60px 72px", animation: "ward-blink 5s infinite" }}>
      <ellipse cx={47 + dx} cy={72 + dy} rx={mood === "worried" ? 5.5 : 5} ry={mood === "worried" ? 7.5 : 7} />
      <ellipse cx={73 + dx} cy={72 + dy} rx={mood === "worried" ? 5.5 : 5} ry={mood === "worried" ? 7.5 : 7} />
      {mood === "worried" && (
        <g fill="none" stroke={ink} strokeWidth="3" strokeLinecap="round">
          <path d="M40 60 l10 -3" />
          <path d="M80 60 l-10 -3" />
        </g>
      )}
    </g>
  );
}

function Mouth({ mood }: { mood: Mood }) {
  const ink = "var(--bg)";
  switch (mood) {
    case "cheer":
      return <path d="M50 86 q10 12 20 0 z" fill={ink} />;
    case "worried":
      return <path d="M54 91 q6 -4 12 0" fill="none" stroke={ink} strokeWidth="3.5" strokeLinecap="round" />;
    case "think":
      return <path d="M55 89 h10" stroke={ink} strokeWidth="3.5" strokeLinecap="round" />;
    case "sleep":
      return <ellipse cx="60" cy="89" rx="3" ry="2.5" fill={ink} />;
    default:
      return <path d="M53 86 q7 7 14 0" fill="none" stroke={ink} strokeWidth="3.5" strokeLinecap="round" />;
  }
}

export function Ghost({ mood = "happy", size = 120, glow = true, className = "", label }: { mood?: Mood; size?: number; glow?: boolean; className?: string; label?: string }) {
  const reduce = useReducedMotion();
  return (
    <motion.div
      className={`relative inline-grid place-items-center ${className}`}
      style={{ width: size, height: size * 1.17 }}
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      key={mood}
      initial={reduce ? false : { scale: 0.92, rotate: mood === "cheer" ? -6 : 0 }}
      animate={{ scale: 1, rotate: 0 }}
      transition={{ type: "spring", stiffness: 260, damping: 14 }}
    >
      {glow && (
        <div
          className="absolute inset-[-28%] rounded-full"
          style={{ background: "radial-gradient(closest-side, var(--halo), transparent 72%)" }}
        />
      )}
      <svg viewBox="0 0 120 140" width="100%" height="100%" style={{ animation: reduce ? undefined : "ward-float 4.5s ease-in-out infinite", overflow: "visible" }}>
        <path d={BODY} fill="var(--ink)" />
        <path d={BODY} fill="url(#ward-sheen)" />
        <defs>
          <radialGradient id="ward-sheen" cx="35%" cy="25%" r="80%">
            <stop offset="0" stopColor="#fff" stopOpacity="0.35" />
            <stop offset="0.6" stopColor="var(--glow)" stopOpacity="0.08" />
            <stop offset="1" stopColor="var(--glow)" stopOpacity="0.22" />
          </radialGradient>
        </defs>
        <ellipse cx="37" cy="86" rx="6" ry="3.5" fill="var(--glow)" opacity={mood === "worried" ? 0 : 0.55} />
        <ellipse cx="83" cy="86" rx="6" ry="3.5" fill="var(--glow)" opacity={mood === "worried" ? 0 : 0.55} />
        <Eyes mood={mood} />
        <Mouth mood={mood} />
      </svg>
    </motion.div>
  );
}

