const TALK: Record<Exercise["kind"], string> = {
  choose: "Hands up for each answer. Why might someone pick a different one?",
  spot: "Point to the message you'd pick. What would you do if you saw this in your group?",
  sort: "Which one was hardest to sort? Why?",
  truefalse: "Stand up for true, stay seated for false. Who has heard someone say this?",
  write: "Two minutes: write your own, then share with the person next to you if you want to.",
};

export function TeachLesson({ id }: { id: string }) {
  const found = lessonById(id);
  const [i, setI] = useState(0);
  const [shown, setShown] = useState(false);
  const total = found?.lesson.exercises.length ?? 0;
  const done = i >= total;

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "ArrowRight" || e.key === " ") {
        e.preventDefault();
        if (!shown && !done) setShown(true);
        else if (!done) {
          setShown(false);
          setI((x) => x + 1);
        }
      }
      if (e.key === "ArrowLeft" && i > 0) {
        setShown(false);
        setI((x) => x - 1);
      }
      if (e.key === "Escape") back({ name: "teach" });
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [shown, done, i]);

  if (!found) return null;
  const ex = found.lesson.exercises[i];

  return (
    <main className="mx-auto flex min-h-[100dvh] max-w-6xl flex-col px-6 py-6 sm:px-10">
      <header className="flex items-center gap-4">
        <button onClick={() => back({ name: "teach" })} className="grid size-11 place-items-center rounded-full text-dim hover:bg-raised" aria-label="End lesson">
          <X size={24} weight="bold" />
        </button>
        <p className="font-display font-semibold text-dim">
          {found.unit.title}: {found.lesson.title}
        </p>
        <p className="ml-auto text-sm font-bold text-dim">{done ? "Done" : `${i + 1} of ${total}`}</p>
      </header>

      <div className="flex flex-1 flex-col justify-center py-8">
        {done ? (
          <div className="flex flex-col items-center text-center">
            <Ghost mood="cheer" size={150} />
            <h1 className="mt-6 font-display text-[clamp(2rem,5vw,3.5rem)] font-bold tracking-tight">That's the lesson.</h1>
            <p className="mt-3 max-w-[50ch] text-[clamp(1.1rem,2vw,1.5rem)] text-dim">
              If anything today felt close to home, you can talk to me after class, or to any adult you trust. You're not on your own with it.
            </p>
          </div>
        ) : ex ? (
          <ClassExercise ex={ex} shown={shown} />
        ) : null}
      </div>

      {!done && (
        <footer className="grid gap-4 border-t border-line pt-5 sm:grid-cols-[1fr_auto] sm:items-center">
          <p className="flex items-start gap-3 text-[clamp(1rem,1.6vw,1.25rem)]">
            <ChatsTeardrop size={26} weight="bold" className="mt-0.5 shrink-0 text-glow" />
            {ex ? TALK[ex.kind] : ""}
          </p>
          <div className="flex gap-2">
            <Button tone="quiet" disabled={i === 0} onClick={() => (setShown(false), setI(i - 1))} aria-label="Previous question">
              <ArrowLeft size={20} weight="bold" />
            </Button>
            {!shown ? (
              <Button onClick={() => setShown(true)}>
                <Eye size={20} weight="bold" /> Reveal
              </Button>
            ) : (
              <Button onClick={() => (setShown(false), setI(i + 1))}>
                Next <ArrowRight size={20} weight="bold" />
              </Button>
            )}
          </div>
        </footer>
      )}
    </main>
  );
}

const BIG = "font-display text-[clamp(1.8rem,4.2vw,3.25rem)] font-bold leading-[1.15] tracking-tight";
const MID = "text-[clamp(1.1rem,2.1vw,1.6rem)]";

function ClassExercise({ ex, shown }: { ex: Exercise; shown: boolean }) {
  const why = "why" in ex ? ex.why : "";
  switch (ex.kind) {
    case "truefalse":
      return (
        <div>
          <p className={`${MID} font-bold text-glow`}>True or false?</p>
          <h1 className={`${BIG} mt-3`}>{ex.statement}</h1>
          {shown && <Answer title={ex.answer ? "True" : "False"} why={why} />}
        </div>
      );
    case "choose":
      return (
        <div>
          <h1 className={BIG}>{ex.prompt}</h1>
          <ol className="mt-8 grid gap-3">
            {ex.options.map((o, k) => (
              <li
                key={o.text}
                className={`flex gap-4 rounded-card border-2 px-6 py-4 ${MID} ${shown ? (o.right ? "border-safe bg-[color-mix(in_srgb,var(--safe),transparent_88%)]" : "border-line opacity-60") : "border-line bg-surface"}`}
              >
                <span className="font-display font-bold text-glow">{String.fromCharCode(65 + k)}</span>
                {o.text}
              </li>
            ))}
          </ol>
          {shown && <Answer why={ex.options.find((o) => o.right)!.why} />}
        </div>
      );
    case "spot":
      return (
        <div>
          <h1 className={BIG}>{ex.prompt}</h1>
          <ol className="mt-8 grid max-w-3xl gap-3">
            {ex.chat.map((l, k) => (
              <li key={k} className={`rounded-card px-6 py-3 ${MID} ${shown && l.flag ? "bg-alarm-soft ring-2 ring-alarm" : "bg-surface"}`}>
                <span className="block text-[0.7em] font-bold text-dim">{l.from}</span>
                {l.text}
              </li>
            ))}
          </ol>
          {shown && <Answer why={why} />}
        </div>
      );
    case "sort":
      return (
        <div>
          <h1 className={BIG}>{ex.prompt}</h1>
          <div className="mt-8 grid gap-3 md:grid-cols-2">
            {shown
              ? ex.bins.map((b, bi) => (
                  <div key={b} className="rounded-card border border-line bg-surface p-5">
                    <p className={`${MID} font-display font-bold text-glow`}>{b}</p>
                    <ul className="mt-3 grid gap-2">
                      {ex.items.filter((it) => it.bin === bi).map((it) => (
                        <li key={it.text} className={MID}>
                          {it.text}
                        </li>
                      ))}
                    </ul>
                  </div>
                ))
              : ex.items.map((it) => (
                  <div key={it.text} className={`rounded-card bg-surface px-6 py-4 ${MID}`}>
                    {it.text}
                  </div>
                ))}
          </div>
          {shown && <Answer why={why} />}
        </div>
      );
    case "write":
      return (
        <div>
          <h1 className={BIG}>{ex.prompt}</h1>
          {shown && <Answer title="One way to say it" why={`"${ex.example}"`} />}
        </div>
      );
  }
}

function Answer({ title, why }: { title?: string; why: string }) {
  return (
    <div className="mt-8 flex max-w-4xl gap-5 rounded-card border border-glow/40 bg-glow-soft p-6">
      <Ghost mood="cheer" size={64} className="hidden shrink-0 sm:inline-grid" />
      <div>
        {title && <p className={`${MID} font-display font-bold text-glow`}>{title}</p>}
        <p className={MID}>{why}</p>
      </div>
    </div>
  );
}

// A report a helpline, school or police officer can act on without a back-and-forth: who, what,
// when, how bad, what the child wants, and proof the messages weren't edited after saving.
// The format is versioned (ward.report/v1) and documented in docs/REPORT.md so a helpline can
// import it, not just read it.

import type { Analysis, Category, Chat, PatternKind, Severity } from "./types.ts";

export const WANTS = {
  stop: "Make it stop",
  remove: "Get something taken down",
  talk: "Talk to someone about how I feel",
  school: "Tell my school",
  police: "Report it to the police",
} as const;

export type Want = keyof typeof WANTS;

export interface ReportInput {
  chat: Chat;
  analysis: Analysis;
  /** SHA-256 per message, in chat order, taken when the evidence was saved. */
  fingerprints: string[];
  savedAt: Date;
  title: string;
  platform: string;
  /** Everything about the child is optional; the child decides what to share. */
  reporter: { firstName?: string; ageBand?: string; city?: string; country?: string };
  inDangerNow: boolean | null;
  wants: Want[];
  /** Who the report is for, so the wording can fit (helpline, school, police, parent). */
  recipient: "helpline" | "school" | "police" | "adult";
  appVersion?: string;
}

export interface ReportIncident {
  at: string | null;
  from: string;
  text: string;
  severity: Severity;
  categories: Category[];
  why: string;
  sha256: string;
}

export interface WardReport {
  schema: "ward.report/v1";
  createdAt: string;
  recipient: ReportInput["recipient"];
  tool: { name: "Ward"; version: string; models: string[]; languages: string[] };
  reporter: ReportInput["reporter"];
  safety: { inDangerNow: boolean | null; level: Analysis["level"]; dangerous: Category[] };
  wants: { id: Want; label: string }[];
  conversation: {
    title: string;
    platform: string;
    source: Chat["source"];
    messages: number;
    participants: number;
    firstIncident: string | null;
    lastIncident: string | null;
    days: number;
  };
  accounts: { name: string; hurtfulMessages: number; worstSeverity: Severity; addedDuringChat: boolean; onlyAttacked: boolean }[];
  patterns: { kind: PatternKind; summary: string }[];
  incidents: ReportIncident[];
  integrity: { algorithm: "SHA-256"; savedAt: string; perMessage: true; digest: string };
}

async function sha256(s: string) {
  const h = await globalThis.crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return [...new Uint8Array(h)].map((x) => x.toString(16).padStart(2, "0")).join("");
}

const DANGER: Category[] = ["threat", "selfharm", "sexual", "exposure"];

export async function buildReport(input: ReportInput): Promise<WardReport> {
  const { chat, analysis: a, fingerprints } = input;
  const self = a.self;
  const hurtful = a.findings.filter((f) => f.severity > 0 && f.message.sender !== self);
  const fp = new Map(chat.messages.map((m, i) => [m.id, fingerprints[i] ?? ""]));
  const incidents: ReportIncident[] = hurtful.map((f) => ({
    at: f.message.at?.toISOString() ?? null,
    from: f.message.sender,
    text: f.message.text,
    severity: f.severity,
    categories: f.categories,
    why: f.why,
    sha256: fp.get(f.message.id) ?? "",
  }));
  const times = incidents.map((i) => i.at).filter((t): t is string => !!t).sort();
  const ghosts = new Set(a.patterns.find((p) => p.kind === "ghosts")?.senders ?? []);
  const added = new Set(chat.events.filter((e) => e.kind === "added" || e.kind === "joined").map((e) => e.who));
  const conversation = {
    title: input.title,
    platform: input.platform,
    source: chat.source,
    messages: chat.messages.length,
    participants: chat.participants.length,
    firstIncident: times[0] ?? null,
    lastIncident: times.at(-1) ?? null,
    days: new Set(times.map((t) => t.slice(0, 10))).size,
  };
  // The digest covers what a reader relies on: the conversation facts and every incident.
  const digest = await sha256(JSON.stringify({ conversation, incidents }));
  return {
    schema: "ward.report/v1",
    createdAt: new Date().toISOString(),
    recipient: input.recipient,
    tool: { name: "Ward", version: input.appVersion ?? "0.1.0", models: a.layers.models, languages: a.layers.packs },
    reporter: Object.fromEntries(Object.entries(input.reporter).filter(([, v]) => v && String(v).trim())) as ReportInput["reporter"],
    safety: {
      inDangerNow: input.inDangerNow,
      level: a.level,
      dangerous: [...new Set(hurtful.flatMap((f) => f.categories).filter((c) => DANGER.includes(c)))],
    },
    wants: input.wants.map((id) => ({ id, label: WANTS[id] })),
    conversation,
    accounts: a.senders
      .filter((s) => s.hostile > 0 && s.name !== self)
      .map((s) => ({ name: s.name, hurtfulMessages: s.hostile, worstSeverity: s.worst, addedDuringChat: added.has(s.name), onlyAttacked: ghosts.has(s.name) })),
    patterns: a.patterns.map((p) => ({ kind: p.kind, summary: p.summary })),
    incidents,
    integrity: { algorithm: "SHA-256", savedAt: input.savedAt.toISOString(), perMessage: true, digest },
  };
}

/** Recompute the digest of a received report, so a helpline can check it wasn't altered. */
export async function verifyReport(r: WardReport): Promise<boolean> {
  return (await sha256(JSON.stringify({ conversation: r.conversation, incidents: r.incidents }))) === r.integrity.digest;
}

export async function fingerprintMessages(chat: Chat): Promise<string[]> {
  return Promise.all(chat.messages.map((m) => sha256(`${m.sender}|${m.at?.toISOString() ?? ""}|${m.text}`)));
}

